#define _POSIX_C_SOURCE 200809L
#include <errno.h>
#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#define USAGE "usage: virtual-dispatch [--size N] [--seed U64] [--repeats N] [--value I32] [--warmup-samples N] [--samples N] --output DIR --run-id ID [--trial N] --target TARGET [--config-id ID]"
typedef struct Operation Operation;struct Operation{int32_t(*process)(const Operation*,int32_t);int32_t operand;};typedef struct{int add;int32_t operand;}Direct;
typedef struct{uint32_t size,repeats,warmup,samples,trial;int32_t value;uint64_t seed;const char*output,*run_id,*target,*config_id;}Config;
static int32_t add(const Operation*o,int32_t v){return(int32_t)((uint32_t)v+(uint32_t)o->operand);}static int32_t mul(const Operation*o,int32_t v){return(int32_t)((uint32_t)v*(uint32_t)o->operand);}
static void fail(const char*s){fprintf(stderr,"error: %s\n%s\n",s,USAGE);exit(2);}static int id(const char*s){if(!s||!((*s>='A'&&*s<='Z')||(*s>='a'&&*s<='z')||(*s>='0'&&*s<='9')))return 0;for(s++;*s;s++)if(!((*s>='A'&&*s<='Z')||(*s>='a'&&*s<='z')||(*s>='0'&&*s<='9')||strchr("._-",*s)))return 0;return 1;}
static uint64_t unum(const char*s,uint64_t max,const char*k){char*e;errno=0;if(!s||!*s||*s=='-')fail(k);uintmax_t v=strtoumax(s,&e,10);if(errno||*e||v>max)fail(k);return(uint64_t)v;}static int64_t snum(const char*s,int64_t lo,int64_t hi,const char*k){char*e;errno=0;if(!s||!*s)fail(k);intmax_t v=strtoimax(s,&e,10);if(errno||*e||v<lo||v>hi)fail(k);return(int64_t)v;}
static Config parse(int argc,char**argv){if(argc==2&&!strcmp(argv[1],"--help")){puts(USAGE);exit(0);}const char*size="100000",*seed=NULL,*repeats="100",*value="1",*warmup="5",*samples="20",*output=NULL,*run_id=NULL,*trial="1",*target=NULL,*config="default";const char**keys[]={&size,&seed,&repeats,&value,&warmup,&samples,&output,&run_id,&trial,&target,&config};const char*names[]={"--size","--seed","--repeats","--value","--warmup-samples","--samples","--output","--run-id","--trial","--target","--config-id"};unsigned seen=0;for(int i=1;i<argc;i+=2){int n=-1;for(int j=0;j<11;j++)if(!strcmp(argv[i],names[j]))n=j;if(n<0)fail("unknown option");if(seen&(1u<<n))fail("duplicate option");if(i+1>=argc)fail("missing option value");seen|=1u<<n;*keys[n]=argv[i+1];}if(!output||!run_id||!target)fail("--output, --run-id, and --target are required");if(strcmp(target,"c-gcc")&&strcmp(target,"c-clang"))fail("invalid C target");if(!id(run_id)||!id(config))fail("invalid identifier");uint64_t sd;if(seed)sd=unum(seed,UINT64_MAX,"invalid --seed");else{FILE*f=fopen("/dev/urandom","rb");if(!f||fread(&sd,sizeof sd,1,f)!=1)fail("cannot generate seed");fclose(f);}Config c={(uint32_t)unum(size,INT32_MAX,"invalid --size"),(uint32_t)unum(repeats,INT32_MAX,"invalid --repeats"),(uint32_t)unum(warmup,INT32_MAX,"invalid --warmup-samples"),(uint32_t)unum(samples,INT32_MAX,"invalid --samples"),(uint32_t)unum(trial,INT32_MAX,"invalid --trial"),(int32_t)snum(value,INT32_MIN,INT32_MAX,"invalid --value"),sd,output,run_id,target,config};if(!c.size||!c.repeats||!c.samples||!c.trial)fail("positive argument required");return c;}
static uint64_t next(uint64_t*s){*s+=UINT64_C(0x9e3779b97f4a7c15);uint64_t z=*s;z=(z^(z>>30))*UINT64_C(0xbf58476d1ce4e5b9);z=(z^(z>>27))*UINT64_C(0x94d049bb133111eb);return z^(z>>31);}static int32_t run(const Operation*ops,uint32_t size,uint32_t repeats,int32_t value){uint32_t sum=0;for(uint32_t n=0;n<repeats;n++)for(uint32_t i=0;i<size;i++)sum+=(uint32_t)ops[i].process(&ops[i],value);return(int32_t)sum;}static int32_t expected(const Direct*d,uint32_t size,uint32_t repeats,int32_t value){uint32_t one=0;for(uint32_t i=0;i<size;i++)one+=d[i].add?(uint32_t)value+(uint32_t)d[i].operand:(uint32_t)value*(uint32_t)d[i].operand;return(int32_t)(one*repeats);}static uint64_t ns(struct timespec t){return(uint64_t)t.tv_sec*1000000000u+(uint64_t)t.tv_nsec;}
static void field(FILE*f,const char*s){if(strpbrk(s,",\"\r\n")){fputc('"',f);for(;*s;s++){if(*s=='"')fputc('"',f);fputc(*s,f);}fputc('"',f);}else fputs(s,f);}static void row(FILE*f,const Config*c,const char*phase,uint32_t index,double elapsed,uint64_t duration,const char*tool,const char*env,const char*caseid){fprintf(f,"2,");field(f,c->run_id);fprintf(f,",virtual-dispatch,");field(f,caseid);fprintf(f,",C,");field(f,c->target);fputc(',',f);field(f,c->config_id);fputc(',',f);field(f,tool);fputc(',',f);field(f,"CMake Release; -O3 -DNDEBUG");fputc(',',f);field(f,env);fprintf(f,",%u,%s,%u,%.6f,time_per_op,%"PRIu64",ns/op\n",c->trial,phase,index,elapsed,duration);}
int main(int argc,char**argv){Config c=parse(argc,argv);Operation*ops=malloc(sizeof(*ops)*c.size);Direct*d=malloc(sizeof(*d)*c.size);if(!ops||!d)fail("allocation failed");uint64_t state=c.seed;for(uint32_t i=0;i<c.size;i++){uint64_t b=next(&state);d[i].add=(int)(b&1);d[i].operand=(int32_t)((b>>1)&15)+1;ops[i].process=d[i].add?add:mul;ops[i].operand=d[i].operand;}int32_t want=expected(d,c.size,c.repeats,c.value);char path[4096];if(snprintf(path,sizeof path,"%s/results.csv",c.output)>=(int)sizeof path)fail("output path too long");FILE*check=fopen(path,"r");int exists=check!=NULL;if(check)fclose(check);FILE*out=fopen(path,"a");if(!out)fail("cannot open results.csv");if(!exists)fputs("schema_version,run_id,benchmark,case_id,language,target,config_id,toolchain,flags,environment,trial,phase,sample,elapsed_ms,metric,value,unit\n",out);char caseid[256];snprintf(caseid,sizeof caseid,"size-%u-repeats-%u-value-%"PRId32"-seed-%"PRIu64,c.size,c.repeats,c.value,c.seed);
#if defined(__clang__)
const char*tool="Clang " __clang_version__;
#elif defined(__GNUC__)
const char*tool="GCC " __VERSION__;
#else
const char*tool="unknown C compiler";
#endif
const char*env=getenv("BENCH_ENVIRONMENT");if(!env)env="unknown";struct timespec start,before,after;clock_gettime(CLOCK_MONOTONIC,&start);int32_t last=0;uint32_t total=c.warmup+c.samples;for(uint32_t i=1;i<=total;i++){clock_gettime(CLOCK_MONOTONIC,&before);last=run(ops,c.size,c.repeats,c.value);clock_gettime(CLOCK_MONOTONIC,&after);if(last!=want){fclose(out);fail("checksum mismatch");}row(out,&c,i<=c.warmup?"warmup":"unclassified",i,(double)(ns(after)-ns(start))/1e6,ns(after)-ns(before),tool,env,caseid);}if(fclose(out))fail("cannot write results.csv");fprintf(stderr,"effective size=%u seed=%"PRIu64" repeats=%u value=%"PRId32" warmup_samples=%u samples=%u run_id=%s trial=%u target=%s config_id=%s\ntoolchain=%s flags=CMake Release; -O3 -DNDEBUG environment=%s\nchecksum=%"PRId32"\n",c.size,c.seed,c.repeats,c.value,c.warmup,c.samples,c.run_id,c.trial,c.target,c.config_id,tool,env,last);free(ops);free(d);return 0;}
